contracts/MockFunctionsRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract MockFunctionsRouter {
    event RequestSent(
        uint64 subscriptionId,
        bytes data,
        uint16 dataVersion,
        uint32 callbackGasLimit,
        bytes32 donId
    );

    function sendRequest(
        uint64 subscriptionId,
        bytes calldata data,
        uint16 dataVersion,
        uint32 callbackGasLimit,
        bytes32 donId
    ) external returns (bytes32) {
        emit RequestSent(subscriptionId, data, dataVersion, callbackGasLimit, donId);
        return keccak256(abi.encodePacked("test-request-id"));
    }

    function sendRequestToProposed(
        uint64 subscriptionId,
        bytes calldata data,
        uint16 dataVersion,
        uint32 callbackGasLimit,
        bytes32 donId
    ) external returns (bytes32) {
        emit RequestSent(subscriptionId, data, dataVersion, callbackGasLimit, donId);
        return keccak256(abi.encodePacked("test-request-id"));
    }

    function fulfill(
        address consumer,
        bytes32 requestId,
        bytes memory response,
        bytes memory err
    ) external {
        (bool success, ) = consumer.call(
            abi.encodeWithSignature("handleOracleFulfillment(bytes32,bytes,bytes)", requestId, response, err)
        );
        require(success, "Fulfill failed");
    }
}

contracts/MockNFTMinter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract MockNFTMinter {
    uint256 public totalMinted;
    uint256 public lastKwh;
    uint256 public lastTimestamp;

    event NFTMinted(uint256 generationKwh, uint256 timestamp);

    function mintNFT(uint256 generationKwh, uint256 timestamp) external {
        totalMinted += 1;
        lastKwh = generationKwh;
        lastTimestamp = timestamp;
        emit NFTMinted(generationKwh, timestamp);
    }
}

contracts/TreetinoKeeper.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AutomationCompatibleInterface} from "@chainlink/contracts/src/v0.8/automation/AutomationCompatible.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

interface ITreetinoOracle {
    function requestEnergyData(string[] calldata args) external returns (bytes32);
    function lastUpdateTimestamp() external view returns (uint256);
}

contract TreetinoKeeper is AutomationCompatibleInterface, Ownable {
    ITreetinoOracle public oracle;
    uint256 public interval;
    string public targetInstallationId;

    constructor(address _oracleAddress, uint256 _interval, string memory _targetInstallationId) Ownable(msg.sender) {
        oracle = ITreetinoOracle(_oracleAddress);
        interval = _interval;
        targetInstallationId = _targetInstallationId;
    }

    function setOracle(address _oracleAddress) external onlyOwner {
        oracle = ITreetinoOracle(_oracleAddress);
    }

    function setInterval(uint256 _interval) external onlyOwner {
        interval = _interval;
    }

    function checkUpkeep(
        bytes calldata /* checkData */
    ) external view override returns (bool upkeepNeeded, bytes memory performData) {
        upkeepNeeded = (block.timestamp - oracle.lastUpdateTimestamp()) > interval;
        // In a production environment, you might calculate start/end timestamps dynamically here
        performData = abi.encode(targetInstallationId);
    }

    function performUpkeep(bytes calldata performData) external override {
        require((block.timestamp - oracle.lastUpdateTimestamp()) > interval, "Upkeep not needed");

        string memory instId = abi.decode(performData, (string));

        // Build the arguments for the Chainlink Functions request
        string[] memory args = new string[](3);
        args[0] = instId;

        // Calculate timestamps dynamically based on the current block and interval
        uint256 endTimestamp = block.timestamp;
        uint256 startTimestamp = endTimestamp - interval;

        args[1] = Strings.toString(startTimestamp);
        args[2] = Strings.toString(endTimestamp);

        oracle.requestEnergyData(args);
    }
}

contracts/TreetinoOracleConsumer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {FunctionsClient} from "@chainlink/contracts/src/v0.8/functions/v1_0_0/FunctionsClient.sol";
import {FunctionsRequest} from "@chainlink/contracts/src/v0.8/functions/v1_0_0/libraries/FunctionsRequest.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

interface INFTMinter {
    function mintNFT(uint256 generationKwh, uint256 timestamp) external;
}

contract TreetinoOracleConsumer is FunctionsClient, Ownable {
    using FunctionsRequest for FunctionsRequest.Request;

    bytes32 public donId;
    uint64 public subscriptionId;
    uint32 public gasLimit;
    string public sourceCode;
    INFTMinter public nftMinter;

    uint256 public lastGenerationKwh;
    uint256 public lastUpdateTimestamp;

    event DataUpdated(bytes32 indexed requestId, uint256 generationKwh, uint256 timestamp);

    constructor(
        address router,
        bytes32 _donId,
        uint64 _subscriptionId,
        uint32 _gasLimit,
        string memory _sourceCode,
        address _nftMinter
    ) FunctionsClient(router) Ownable(msg.sender) {
        donId = _donId;
        subscriptionId = _subscriptionId;
        gasLimit = _gasLimit;
        sourceCode = _sourceCode;
        nftMinter = INFTMinter(_nftMinter);
    }

    function updateSourceCode(string memory _newSourceCode) external onlyOwner {
        sourceCode = _newSourceCode;
    }

    function setNFTMinter(address _nftMinter) external onlyOwner {
        nftMinter = INFTMinter(_nftMinter);
    }

    function requestEnergyData(
        string[] calldata args
    ) external returns (bytes32 requestId) {
        FunctionsRequest.Request memory req;
        req.initializeRequestForInlineJavaScript(sourceCode);
        if (args.length > 0) {
            req.setArgs(args);
        }

        requestId = _sendRequest(
            req.encodeCBOR(),
            subscriptionId,
            gasLimit,
            donId
        );
    }

    function fulfillRequest(
        bytes32 requestId,
        bytes memory response,
        bytes memory err
    ) internal override {
        if (err.length > 0) {
            revert(string(err));
        }

        lastGenerationKwh = abi.decode(response, (uint256));
        lastUpdateTimestamp = block.timestamp;

        // Trigger the NFT minting step if a minter is configured
        if (address(nftMinter) != address(0)) {
            nftMinter.mintNFT(lastGenerationKwh, block.timestamp);
        }

        emit DataUpdated(requestId, lastGenerationKwh, block.timestamp);
    }
}

